<?php include "../includes/header.php"; ?><h2>Task 9 - Boolean Values</h2><div class="result"><?php $tests=[1,"tariq",1.5,true,7,'s',false]; echo "<h5>Using For Loop</h5>"; for($i=0;$i<count($tests);$i++){if(is_bool($tests[$i])){echo ($tests[$i]?"Yes":"No")."<br>";}else{echo htmlspecialchars((string)$tests[$i])."<br>";}} echo "<h5>Using While Loop</h5>"; $i=0; while($i<count($tests)){if(is_bool($tests[$i])){echo ($tests[$i]?"Yes":"No")."<br>";}else{echo htmlspecialchars((string)$tests[$i])."<br>";}$i++;} ?><?php if(isset($message)) echo $message; ?></div><a href="../index.php" class="btn btn-secondary mt-3">Back</a><?php include "../includes/footer.php"; ?>